package com.threatstream.detection;
import java.time.Instant; import java.util.*; import org.springframework.stereotype.Component;
@Component class PasswordSprayingRule implements DetectionRule { private final DetectionProperties p; private final AlertFactory f; private final Map<String,Deque<AuthEvent>> state=new HashMap<>(); private final Set<String> armed=new HashSet<>(); PasswordSprayingRule(DetectionProperties p,AlertFactory f){this.p=p;this.f=f;}
 public synchronized Optional<SecurityAlert> evaluate(AuthEvent e){ Deque<AuthEvent> q=state.computeIfAbsent(e.sourceIp(),x->new ArrayDeque<>()); Instant cut=e.timestamp().minus(p.passwordSpraying().window()); while(!q.isEmpty()&&q.peek().timestamp().isBefore(cut))q.remove(); if(q.isEmpty())armed.remove(e.sourceIp()); q.add(e); int users=(int)q.stream().map(AuthEvent::username).distinct().count(); return users>=p.passwordSpraying().threshold()&&armed.add(e.sourceIp())?Optional.of(f.create("AUTH_PASSWORD_SPRAYING","PASSWORD_SPRAYING","HIGH",e,users,q.peek().timestamp())):Optional.empty(); } }
